const r = await api.get('/customers', {});
// r is {items: [...], count: number}
const novCustomers = r.items.filter(c => {
  if (!c.birth_date) return false;
  // assume format YYYY-MM-DD or similar
  const month = new Date(c.birth_date).getMonth() + 1; // JS months 0-11
  return month === 11;
});
return {count: novCustomers.length};

